  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * ## Connection lifecycle
 11→ *
 12→ * 1. Connect to `ws://<host>:9900/browser`.
 13→ * 2. Server sends `agent_list` (sidebar metadata) + `task_list`. No
 14→ *    message histories are sent eagerly — this keeps the initial
 15→ *    payload small for fast loading on mobile networks.
 16→ * 3. `initialLoadDone` becomes true after `agent_list` arrives.
 17→ * 4. The first agent is auto-selected if nothing was selected.
 18→ *
 19→ * ## Lazy history loading
 20→ *
 21→ * Message histories are loaded on demand. When `activeAgentId` changes
 22→ * and the agent hasn't been loaded yet, the hook sends
 23→ * `{ type: "request_history", agentId }` and sets `historyLoading = true`.
 24→ * When the server responds with `message_history`, the agent's messages
 25→ * are populated and `historyLoading` becomes false.
 26→ *
 27→ * The `loadedAgents` Set tracks which agents have been fetched so that
 28→ * switching back to a previously viewed agent is instant.
 29→ *
 30→ * ## Resilience features
 31→ *
 32→ * - Handles `message_history` replay from server on demand.
 33→ * - Handles `cli_disconnected` / `cli_connected` events.
 34→ * - Deduplicates messages using a per-agent processed count.
 35→ * - Robust reconnection guard (clears previous timer before scheduling).
 36→ * - Strict mode safe (closingRef prevents spurious reconnects on unmount).
 37→ *
 38→ * ## Logging
 39→ *
 40→ * All WS events are logged with the `[thos-ws]` prefix. Filter by this
 41→ * in the browser console to debug connection and message delivery issues.
 42→ */
 43→
 44→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 45→import type {
 46→  AgentInfo,
 47→  AgentStatus,
 48→  ChatMessage,
 49→  ClaudeAssistant,
 50→  ClaudeControlRequest,
 51→  ClaudeMessage,
 52→  ClaudeResult,
 53→  ClaudeSystemInit,
 54→  ServerMessage,
 55→  ServerMessageHistory,
 56→  ServerTaskList,
 57→  ServerTaskUpdated,
 58→  ServerTaskDeleted,
 59→  Task,
 60→  TaskPriority,
 61→  ToolCallInfo,
 62→  UserQuestion,
 63→} from "@/lib/types";
 64→
 65→/** Connect to the WS server on the same host the page was loaded from. */
 66→const WS_URL =
 67→  typeof window !== "undefined"
 68→    ? `ws://${window.location.hostname}:9900/browser`
 69→    : "ws://localhost:9900/browser";
 70→
 71→/** Per-agent client state. */
 72→export interface AgentClientState {
 73→  status: AgentStatus;
 74→  messages: ChatMessage[];
 75→  /** Raw Claude NDJSON messages for debug view. */
 76→  rawMessages: ClaudeMessage[];
 77→  label: string;
 78→  tmuxSession: string | null;
 79→  createdAt: number;
 80→}
 81→
 82→/**
 83→ * Extract displayable text from a Claude assistant message.
 84→ * Content blocks may be text, tool_use, or tool_result — each is
 85→ * handled defensively since the array structure can vary.
 86→ */
 87→function extractText(msg: ClaudeAssistant): string {
 88→  const blocks = msg.message?.content;
 89→  if (!blocks || !Array.isArray(blocks)) return "";
 90→  return blocks
 91→    .map((b) => {
 92→      if (b.type === "text") return b.text;
 93→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 94→      if (b.type === "tool_result") {
 95→        const c = (b as { content?: unknown }).content;
 96→        return `[tool_result: ${typeof c === "string" ? c : JSON.stringify(c)}]`;
 97→      }
 98→      return "";
 99→    })
100→    .filter(Boolean)
101→    .join("\n");
102→}
103→
104→/** Module-level counter for generating unique message IDs. */
105→let msgCounter = 0;
106→function nextId() {
107→  return `msg-${Date.now()}-${++msgCounter}`;
108→}
109→
110→/**
111→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
112→ * Used both for live messages and for replaying message_history.
113→ */
114→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
115→  if (relayMsg.type === "relay") {
116→    const msg = relayMsg.message;
117→
118→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
119→      const init = msg as ClaudeSystemInit;
120→      return {
121→        id: nextId(),
122→        role: "system",
123→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
124→        timestamp: Date.now(),
125→      };
126→    }
127→
128→    if (msg.type === "user") {
129→      const rawContent = (msg as { message?: { content?: unknown } }).message?.content ?? "";
130→      // Only render human-typed user messages (string content).
131→      // CLI tool_result messages have array content — these are internal
132→      // protocol messages and are only visible in the raw message viewer.
133→      if (typeof rawContent !== "string") return null;
134→      if (!rawContent.trim()) return null;
135→      return {
136→        id: nextId(),
137→        role: "user",
138→        content: rawContent,
139→        timestamp: Date.now(),
140→      };
141→    }
142→
143→    if (msg.type === "assistant") {
144→      const assistant = msg as ClaudeAssistant;
145→      const text = extractText(assistant);
146→      if (!text) return null;
147→
148→      const blocks = assistant.message?.content ?? [];
149→      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
150→      const toolCalls: ToolCallInfo[] = blocks
151→        .filter((b) => b.type === "tool_use")
152→        .map((b) => ({
153→          name: (b as { name: string }).name,
154→          toolUseId: (b as { id: string }).id,
155→        }));
156→      const isToolOnly = !hasText && toolCalls.length > 0;
157→
158→      return {
159→        id: nextId(),
160→        role: "assistant",
161→        content: text,
162→        timestamp: Date.now(),
163→        toolCalls,
164→        isToolOnly,
165→      };
166→    }
167→
168→    if (msg.type === "result") {
169→      const result = msg as ClaudeResult;
170→      const summary = result.is_error
171→        ? `Error: ${result.error}`
172→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
173→      return {
174→        id: nextId(),
175→        role: "system",
176→        content: summary,
177→        timestamp: Date.now(),
178→      };
179→    }
180→
181→    if (msg.type === "control_request") {
182→      const cr = msg as ClaudeControlRequest;
183→
184→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
185→      if (cr.request.tool_name === "AskUserQuestion") {
186→        const input = cr.request.input as { questions?: UserQuestion[] };
187→        const questions = Array.isArray(input.questions) ? input.questions : [];
188→        return {
189→          id: nextId(),
190→          role: "system",
191→          content: "Question from Claude",
192→          timestamp: Date.now(),
193→          userQuestion: {
194→            requestId: cr.request_id,
195→            questions,
196→          },
197→        };
198→      }
199→
200→      return {
201→        id: nextId(),
202→        role: "system",
203→        content: `Tool approval requested: ${cr.request.tool_name}`,
204→        timestamp: Date.now(),
205→        controlRequest: {
206→          id: cr.request_id,
207→          tool_name: cr.request.tool_name,
208→          input: cr.request.input,
209→        },
210→      };
211→    }
212→  }
213→
214→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
215→    return {
216→      id: nextId(),
217→      role: "system",
218→      content: `Error: ${relayMsg.error}`,
219→      timestamp: Date.now(),
220→    };
221→  }
222→
223→  return null;
224→}
225→
226→/** Console logger with [thos] prefix for easy filtering. */
227→function log(...args: unknown[]) {
228→  console.log("[thos-ws]", ...args);
229→}
230→
231→export function useWebSocket() {
232→  const wsRef = useRef<WebSocket | null>(null);
233→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
234→  /** Set to true during cleanup to prevent onclose from scheduling reconnects. */
235→  const closingRef = useRef(false);
236→  const [connected, setConnected] = useState(false);
237→  /** True once we've received the initial agent_list from the server. */
238→  const [initialLoadDone, setInitialLoadDone] = useState(false);
239→
240→  // Multi-agent state
241→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
242→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
243→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
244→
245→  // Task state
246→  const [tasks, setTasks] = useState<Task[]>([]);
247→
248→  // Per-agent deduplication: track count of processed messages per agent
249→  // to avoid duplicating messages already in local state during history replay.
250→  const processedCountRef = useRef<Map<string, number>>(new Map());
251→
252→  // Track which agents have had their history loaded (lazy loading).
253→  const [loadedAgents, setLoadedAgents] = useState<Set<string>>(new Set());
254→
255→  /** Immutably update a single agent's state in the Map. */
256→  const updateAgent = useCallback(
257→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
258→      setAgents((prev) => {
259→        const existing = prev.get(agentId);
260→        if (!existing) return prev;
261→        const next = new Map(prev);
262→        next.set(agentId, updater(existing));
263→        return next;
264→      });
265→    },
266→    []
267→  );
268→
269→  const connect = useCallback(() => {
270→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
271→    if (wsRef.current) {
272→      wsRef.current.close();
273→      wsRef.current = null;
274→    }
275→
276→    // Reset dedup counts on new connection — server will send fresh history
277→    processedCountRef.current.clear();
278→    setInitialLoadDone(false);
279→    setLoadedAgents(new Set());
280→
281→    log("connecting to", WS_URL);
282→    const ws = new WebSocket(WS_URL);
283→    wsRef.current = ws;
284→
285→    ws.onopen = () => {
286→      log("connected");
287→      setConnected(true);
288→    };
289→
290→    ws.onclose = () => {
291→      log("disconnected, closingRef =", closingRef.current);
292→      setConnected(false);
293→      wsRef.current = null;
294→      // Don't reconnect if the close was triggered by cleanup (e.g. strict mode unmount)
295→      if (closingRef.current) return;
296→      // Reconnection guard: clear any existing timer before scheduling
297→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
298→      log("scheduling reconnect in 2s");
299→      reconnectTimer.current = setTimeout(() => connect(), 2000);
300→    };
301→
302→    ws.onerror = (e) => {
303→      log("error", e);
304→      // onclose will fire after onerror, which triggers reconnect
305→    };
306→
307→    ws.onmessage = (event) => {
308→      let data: ServerMessage;
309→      try {
310→        data = JSON.parse(event.data as string);
311→      } catch {
312→        return;
313→      }
314→
315→      log("←", data.type, "agentId" in data ? (data as { agentId: string }).agentId : "");
316→
317→      // ── task_list: full task list from server ──
318→      if (data.type === "task_list") {
319→        log("task_list:", (data as ServerTaskList).tasks.length, "tasks");
320→        setTasks((data as ServerTaskList).tasks);
321→        return;
322→      }
323→
324→      // ── task_updated: single task changed ──
325→      if (data.type === "task_updated") {
326→        const updated = (data as ServerTaskUpdated).task;
327→        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
328→        return;
329→      }
330→
331→      // ── task_deleted: remove task ──
332→      if (data.type === "task_deleted") {
333→        const deletedId = (data as ServerTaskDeleted).taskId;
334→        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
335→        return;
336→      }
337→
338→      // ── message_history: replay full history from server ──
339→      if (data.type === "message_history") {
340→        const historyMsg = data as ServerMessageHistory;
341→        const agentId = historyMsg.agentId;
342→        const serverMessages = historyMsg.messages;
343→        log("message_history:", agentId, serverMessages.length, "raw msgs");
344→
345→        // Convert all server messages to ChatMessages + extract raw Claude messages
346→        const chatMessages: ChatMessage[] = [];
347→        const rawMessages: ClaudeMessage[] = [];
348→        for (const sm of serverMessages) {
349→          if (sm.type === "relay") {
350→            rawMessages.push(sm.message);
351→          }
352→          const cm = relayChatMessage(agentId, sm);
353→          if (cm) chatMessages.push(cm);
354→        }
355→        log("message_history:", agentId, "→", chatMessages.length, "chat msgs,", rawMessages.length, "raw");
356→
357→        // Always replace local messages with server history (source of truth).
358→        setAgents((prev) => {
359→          const existing = prev.get(agentId);
360→          if (!existing) {
361→            log("message_history:", agentId, "agent not in map yet, creating");
362→            const next = new Map(prev);
363→            next.set(agentId, {
364→              status: "idle",
365→              messages: chatMessages,
366→              rawMessages,
367→              label: "",
368→              tmuxSession: null,
369→              createdAt: 0,
370→            });
371→            return next;
372→          }
373→          const next = new Map(prev);
374→          next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
375→          return next;
376→        });
377→
378→        processedCountRef.current.set(agentId, chatMessages.length);
379→        setLoadedAgents((prev) => {
380→          if (prev.has(agentId)) return prev;
381→          const next = new Set(prev);
382→          next.add(agentId);
383→          return next;
384→        });
385→        return;
386→      }
387→
388→      // ── history_cleared: wipe local messages for this agent ──
389→      if (data.type === "history_cleared") {
390→        updateAgent(data.agentId, (prev) => ({
391→          ...prev,
392→          messages: [],
393→          rawMessages: [],
394→        }));
395→        processedCountRef.current.set(data.agentId, 0);
396→        return;
397→      }
398→
399→      // ── cli_disconnected: show system message ──
400→      if (data.type === "cli_disconnected") {
401→        updateAgent(data.agentId, (prev) => ({
402→          ...prev,
403→          messages: [
404→            ...prev.messages,
405→            {
406→              id: nextId(),
407→              role: "system",
408→              content: "CLI session ended",
409→              timestamp: Date.now(),
410→            },
411→          ],
412→        }));
413→        return;
414→      }
415→
416→      // ── cli_connected: show system message ──
417→      if (data.type === "cli_connected") {
418→        updateAgent(data.agentId, (prev) => {
419→          const isReconnect = prev.messages.length > 0;
420→          return {
421→            ...prev,
422→            messages: [
423→              ...prev.messages,
424→              {
425→                id: nextId(),
426→                role: "system",
427→                content: isReconnect ? "CLI reconnected" : "CLI connected",
428→                timestamp: Date.now(),
429→              },
430→            ],
431→          };
432→        });
433→        return;
434→      }
435→
436→      // ── agent_list: reconcile sidebar state from server ──
437→      if (data.type === "agent_list") {
438→        const serverAgents = data.agents as AgentInfo[];
439→        log("agent_list:", serverAgents.length, "agents:", serverAgents.map((a) => `${a.agentId}(${a.status})`).join(", "));
440→        setAgents((prev) => {
441→          const next = new Map(prev);
442→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
443→
444→          // Update or add agents from server
445→          for (const info of serverAgents) {
446→            const existing = next.get(info.agentId);
447→            if (existing) {
448→              next.set(info.agentId, {
449→                ...existing,
450→                status: info.status,
451→                tmuxSession: info.tmuxSession,
452→                label: info.label,
453→              });
454→            } else {
455→              next.set(info.agentId, {
456→                status: info.status,
457→                messages: [],
458→                rawMessages: [],
459→                label: info.label,
460→                tmuxSession: info.tmuxSession,
461→                createdAt: info.createdAt,
462→              });
463→            }
464→          }
465→
466→          // Remove agents no longer on the server
467→          for (const id of next.keys()) {
468→            if (!serverIds.has(id)) {
469→              next.delete(id);
470→            }
471→          }
472→
473→          return next;
474→        });
475→        setAgentOrder(serverAgents.map((a) => a.agentId));
476→        setInitialLoadDone(true);
477→
478→        // Auto-select the first agent on initial load when nothing is selected
479→        setActiveAgentId((prev) => {
480→          if (prev !== null) return prev;
481→          if (serverAgents.length === 0) return null;
482→          return serverAgents[0].agentId;
483→        });
484→        return;
485→      }
486→
487→      // ── spawned: auto-select the newly created agent ──
488→      if (data.type === "spawned") {
489→        setActiveAgentId(data.agentId);
490→        return;
491→      }
492→
493→      // ── status: update a specific agent's status ──
494→      if (data.type === "status") {
495→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
496→        return;
497→      }
498→
499→      // ── error: append to agent's message list ──
500→      if (data.type === "error") {
501→        updateAgent(data.agentId, (prev) => ({
502→          ...prev,
503→          messages: [
504→            ...prev.messages,
505→            {
506→              id: nextId(),
507→              role: "system",
508→              content: `Error: ${data.error}`,
509→              timestamp: Date.now(),
510→            },
511→          ],
512→        }));
513→        // Track processed count for dedup
514→        processedCountRef.current.set(
515→          data.agentId,
516→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
517→        );
518→        return;
519→      }
520→
521→      // ── relay: append claude message to agent's history ──
522→      if (data.type === "relay") {
523→        const agentId = data.agentId;
524→        const rawMsg = data.message;
525→        const chatMsg = relayChatMessage(agentId, data);
526→
527→        updateAgent(agentId, (prev) => ({
528→          ...prev,
529→          rawMessages: [...prev.rawMessages, rawMsg],
530→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
531→        }));
532→        if (chatMsg) {
533→          // Track processed count for dedup
534→          processedCountRef.current.set(
535→            agentId,
536→            (processedCountRef.current.get(agentId) ?? 0) + 1
537→          );
538→        }
539→        return;
540→      }
541→    };
542→  }, [updateAgent]);
