279→// ── Helpers ────────────────────────────────────────────────────────────────
280→
281→/** Send a JSON message to all connected browsers. */
282→function sendToBrowser(msg: ServerMessage) {
283→  const payload = JSON.stringify(msg);
284→  for (const ws of browserSockets) {
285→    if (ws.readyState === WebSocket.OPEN) {
286→      ws.send(payload);
287→    }
288→  }
289→}
290→
291→/** Build a snapshot of all agents for the sidebar. */
292→function buildAgentList(): AgentInfo[] {
293→  return Array.from(agents.values()).map((a) => ({
294→    agentId: a.agentId,
295→    status: a.status,
296→    tmuxSession: a.tmuxSession,
297→    label: a.label,
298→    createdAt: a.createdAt,
299→  }));
300→}
301→
302→/** Send the full agent list to all browsers. */
303→function broadcastAgentList() {
304→  sendToBrowser({ type: "agent_list", agents: buildAgentList() });
305→}
306→
307→/** Update an agent's status, notify browsers, broadcast list, and persist. */
308→function setAgentStatus(agentId: string, status: AgentStatus) {
309→  const agent = agents.get(agentId);
310→  if (!agent) return;
311→  agent.status = status;
312→  sendToBrowser({ type: "status", agentId, status });
313→  broadcastAgentList();
314→  persistAgentSync(agent);
315→}
316→
317→/**
318→ * Extract a stable dedup key from a relay message, if present.
319→ *
320→ * Claude NDJSON sends cumulative snapshots for two message types:
321→ * - `assistant` — keyed by `message.id` (e.g. `msg_01VE1P7c...`)
322→ * - `user` (tool_result) — keyed by top-level `uuid` (e.g. `b217b852-...`)
323→ *
324→ * We deduplicate by replacing the previous snapshot in `messageHistory`
325→ * instead of appending, reducing storage from O(n²) to O(n).
326→ */
327→function getRelayMessageId(msg: ServerMessage): string | null {
328→  if (msg.type !== "relay") return null;
329→  const inner = msg.message;
330→  if (inner.type === "assistant") {
331→    return (inner as { message?: { id?: string } }).message?.id ?? null;
332→  }
333→  if (inner.type === "user") {
334→    return (inner as { uuid?: string }).uuid ?? null;
335→  }
336→  return null;
337→}
338→
339→/**
340→ * Record a message in the agent's history and send to all browsers.
341→ *
342→ * For cumulative snapshot messages (assistant, user/tool_result), replaces the
343→ * previous snapshot with the same message ID instead of appending. This keeps
344→ * only the final version of each message, dramatically reducing file sizes
345→ * (e.g. 38 MB → ~1 MB for a typical session).
346→ */
347→function recordAndSend(agentId: string, msg: ServerMessage) {
348→  const agent = agents.get(agentId);
349→  if (agent) {
350→    const msgId = getRelayMessageId(msg);
351→    if (msgId) {
352→      // Replace previous snapshot with same message ID (search from end for speed)
353→      let replaced = false;
354→      for (let i = agent.messageHistory.length - 1; i >= 0; i--) {
355→        if (getRelayMessageId(agent.messageHistory[i]) === msgId) {
356→          agent.messageHistory[i] = msg;
357→          replaced = true;
358→          break;
359→        }
360→      }
361→      if (!replaced) {
362→        agent.messageHistory.push(msg);
363→      }
364→    } else {
365→      agent.messageHistory.push(msg);
366→    }
367→    persistAgent(agent); // debounced — streaming messages come fast
368→  }
369→  sendToBrowser(msg);
370→}
