372→// ── Agent lifecycle ────────────────────────────────────────────────────────
373→
374→/**
375→ * Stop a running agent by killing its tmux session and closing the CLI socket.
376→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
377→ */
378→function stopAgent(agentId: string) {
379→  const agent = agents.get(agentId);
380→  if (!agent) return;
381→
382→  if (agent.tmuxSession) {
383→    try {
384→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
385→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
386→    } catch {
387→      // Session may already be dead
388→    }
389→  }
390→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
391→    agent.claudeSocket.close();
392→  }
393→  agent.claudeSocket = null;
394→  setAgentStatus(agentId, "done");
395→}
396→
397→/**
398→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
399→ */
400→function deleteAgent(agentId: string) {
401→  const agent = agents.get(agentId);
402→  if (!agent) return;
403→
404→  if (agent.tmuxSession) {
405→    try {
406→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
407→    } catch {}
408→  }
409→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
410→    agent.claudeSocket.close();
411→  }
412→  agents.delete(agentId);
413→  store.remove(agentId);
414→  broadcastAgentList();
415→}
416→
417→/**
418→ * Spawn a new Claude CLI process inside a tmux session.
419→ *
420→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
421→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
422→ */
423→function spawnClaude(prompt: string): string {
424→  const agentId = newAgentId();
425→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
426→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
427→
428→  const agent: AgentState = {
429→    agentId,
430→    claudeSocket: null,
431→    tmuxSession: null,
432→    pendingPrompt: prompt,
433→    status: "spawning",
434→    label,
435→    createdAt: Date.now(),
436→    sessionId: null,
437→    pendingControlRequests: new Map(),
438→    messageHistory: [],
439→    pendingMessages: [],
440→  };
441→  agents.set(agentId, agent);
442→
443→  // Notify browsers
444→  sendToBrowser({ type: "spawned", agentId });
445→  broadcastAgentList();
446→  persistAgentSync(agent);
447→
448→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
449→  // tmux new-session runs detached (-d) so spawn() returns immediately.
450→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
451→
452→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
453→    stdio: "ignore",
454→  });
455→
456→  tmux.on("error", (err) => {
457→    console.error("[tmux spawn error]", err);
458→    setAgentStatus(agentId, "error");
459→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
460→  });
461→
462→  tmux.on("exit", (code) => {
463→    if (code !== 0) {
464→      console.error(`[tmux] new-session exited with code ${code}`);
465→      setAgentStatus(agentId, "error");
466→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
467→      return;
468→    }
469→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
470→    agent.tmuxSession = sessionName;
471→    broadcastAgentList();
472→    persistAgentSync(agent);
473→  });
474→
475→  return agentId;
476→}
477→
478→// ── Message handlers ───────────────────────────────────────────────────────
479→
480→/**
481→ * Process an incoming NDJSON message from a specific Claude CLI.
482→ *
483→ * Status flow matches the Companion protocol:
484→ * - hook_response → send pending prompt → "thinking"
485→ * - system/init   → "connected" + capture session_id
486→ * - assistant      → "thinking"
487→ * - result         → "connected" (CLI stays alive for multi-turn)
488→ * - CLI disconnect → "done" (handled in connection close handler)
489→ */
490→function handleClaudeMessage(agentId: string, raw: string) {
491→  const agent = agents.get(agentId);
492→  if (!agent) return;
493→
494→  let msg: ClaudeMessage;
495→  try {
496→    msg = JSON.parse(raw);
497→  } catch {
498→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
499→    return;
500→  }
501→
502→  // Silently ignore keep_alive messages
503→  if (msg.type === "keep_alive") return;
504→
505→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
506→
507→  // After hook_response, send the pending prompt
508→  if (
509→    msg.type === "system" &&
510→    (msg as { subtype?: string }).subtype === "hook_response" &&
511→    agent.pendingPrompt &&
512→    agent.claudeSocket?.readyState === WebSocket.OPEN
513→  ) {
514→    const userMsg = JSON.stringify({
515→      type: "user",
516→      message: { role: "user", content: agent.pendingPrompt },
517→      parent_tool_use_id: null,
518→      session_id: agent.sessionId ?? "",
519→    });
520→    console.log(`[server → claude:${agentId}]`, userMsg);
521→    agent.claudeSocket.send(userMsg + "\n");
522→    agent.pendingPrompt = null;
523→    setAgentStatus(agentId, "thinking");
524→  }
525→
526→  // Track status based on message type
527→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
528→    // Capture session_id for subsequent user messages
529→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
530→    setAgentStatus(agentId, "connected");
531→  } else if (msg.type === "assistant") {
532→    setAgentStatus(agentId, "thinking");
533→  } else if (msg.type === "result") {
534→    // CLI stays alive after result — ready for the next turn.
535→    // Status only goes to "done" when the CLI WebSocket actually closes.
536→    setAgentStatus(agentId, "connected");
537→  }
538→
539→  // Store control_request inputs for building proper responses later
540→  if (msg.type === "control_request") {
541→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
542→    if (cr.request_id && cr.request?.input) {
543→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
544→    }
545→  }
546→
547→  // Record in history and relay to browsers
548→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
549→}
550→
551→/**
552→ * Process an incoming JSON message from the browser.
553→ * - `spawn`: create a new agent (does NOT kill others).
554→ * - `send_message`: forward a follow-up user message to the specified agent.
555→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
556→ * - `kill_agent`: stop the CLI and tmux session.
557→ * - `delete_agent`: permanently remove an agent.
558→ * - `rename_agent`: update an agent's label.
559→ * - `clear_history`: wipe an agent's message history.
560→ * - `request_history`: send message history for a single agent (lazy loading).
561→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
562→ */
563→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
564→  let msg: BrowserMessage;
565→  try {
566→    msg = JSON.parse(raw);
567→  } catch {
568→    console.error("[browser] invalid JSON:", raw);
569→    return;
570→  }
571→
572→  console.log("[browser →]", msg.type);
573→
574→  switch (msg.type) {
575→    case "spawn":
576→      spawnClaude(msg.prompt);
577→      break;
578→
579→    case "send_message": {
580→      const agent = agents.get(msg.agentId);
581→      if (!agent) {
582→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
583→        break;
584→      }
585→
586→      // Record the user message in history so it persists across reloads.
587→      // Do NOT broadcast — the sending browser already has it optimistically,
588→      // and other browsers will get it when they request_history.
589→      agent.messageHistory.push({
590→        type: "relay",
591→        agentId: msg.agentId,
592→        message: { type: "user", message: { role: "user", content: msg.content } },
593→      } as ServerMessage);
594→      persistAgent(agent);
595→
596→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
597→        const userMsg = JSON.stringify({
598→          type: "user",
599→          message: { role: "user", content: msg.content },
600→          parent_tool_use_id: null,
601→          session_id: agent.sessionId ?? "",
602→        });
603→        agent.claudeSocket.send(userMsg + "\n");
604→        setAgentStatus(msg.agentId, "thinking");
605→      } else {
606→        // Queue message for delivery when CLI reconnects
607→        const userMsg = JSON.stringify({
608→          type: "user",
609→          message: { role: "user", content: msg.content },
610→          parent_tool_use_id: null,
611→          session_id: agent.sessionId ?? "",
612→        });
613→        agent.pendingMessages.push(userMsg);
614→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
615→        persistAgentSync(agent);
616→      }
617→      break;
618→    }
619→
620→    case "control_response": {
621→      const agent = agents.get(msg.agentId);
622→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
623→        // Retrieve the original tool input to include as updatedInput (required by protocol)
624→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
625→        agent.pendingControlRequests.delete(msg.request_id);
626→
627→        // If the browser sent answers (from AskUserQuestion), merge them into the input
628→        const answers = (msg as { answers?: Record<string, string> }).answers;
629→        const updatedInput = answers
630→          ? { ...originalInput, answers }
631→          : originalInput;
632→
633→        const response = JSON.stringify({
634→          type: "control_response",
635→          response: {
636→            subtype: "success",
637→            request_id: msg.request_id,
638→            response: msg.allow
639→              ? { behavior: "allow", updatedInput }
640→              : { behavior: "deny", message: "Denied by user" },
641→          },
642→        });
643→        agent.claudeSocket.send(response + "\n");
644→      }
645→      break;
646→    }
647→
648→    case "kill_agent":
649→      stopAgent(msg.agentId);
650→      break;
651→
652→    case "delete_agent":
653→      deleteAgent(msg.agentId);
654→      break;
655→
656→    case "rename_agent": {
657→      const agent = agents.get(msg.agentId);
658→      if (!agent) break;
659→      agent.label = msg.label;
660→      broadcastAgentList();
661→      persistAgentSync(agent);
662→      break;
663→    }
664→
665→    case "clear_history": {
666→      const agent = agents.get(msg.agentId);
667→      if (!agent) break;
668→      agent.messageHistory = [];
669→      persistAgentSync(agent);
670→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
671→      break;
672→    }
673→
674→    case "request_history": {
675→      console.log(`[browser] request_history for ${msg.agentId}`);
676→      sendHistoryToSocket(senderWs, msg.agentId);
677→      break;
678→    }
679→
680→    case "create_task": {
681→      const taskId = randomBytes(4).toString("hex");
682→      const task: Task = {
683→        id: taskId,
684→        title: msg.title,
685→        description: msg.description,
686→        status: "todo",
687→        priority: msg.priority,
688→        agentId: null,
689→        createdAt: Date.now(),
690→        updatedAt: Date.now(),
691→      };
692→      tasks.set(taskId, task);
693→      persistTasks();
694→      broadcastTaskList();
695→      break;
696→    }
697→
698→    case "update_task": {
699→      const task = tasks.get(msg.taskId);
700→      if (!task) break;
701→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
702→      persistTasks();
703→      broadcastTaskList();
704→      break;
705→    }
706→
707→    case "delete_task": {
708→      tasks.delete(msg.taskId);
709→      persistTasks();
710→      broadcastTaskList();
711→      break;
712→    }
713→
714→    case "delegate_task": {
715→      const task = tasks.get(msg.taskId);
716→      if (!task) break;
717→      const prompt = `Task: ${task.title}\n\n${task.description}`;
718→      const agentId = spawnClaude(prompt);
719→      task.agentId = agentId;
720→      task.status = "in-progress";
721→      task.updatedAt = Date.now();
722→      persistTasks();
723→      broadcastTaskList();
724→      break;
725→    }
726→  }
727→}
