729→// ── Send message history to a single browser socket ────────────────────────
730→
731→/** Send initial state (agent list + tasks) to a newly connected browser. */
732→function sendFullStateToSocket(ws: WebSocket) {
733→  if (ws.readyState !== WebSocket.OPEN) return;
734→
735→  // Agent list (sidebar metadata) — message histories are loaded lazily on demand
736→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
737→
738→  // Task list
739→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList() }));
740→}
741→
742→/** Send message history for a single agent to a specific browser socket. */
743→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
744→  const agent = agents.get(agentId);
745→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
746→  ws.send(
747→    JSON.stringify({
748→      type: "message_history",
749→      agentId: agent.agentId,
750→      messages: agent.messageHistory,
751→    })
752→  );
753→}
754→
755→// ── Connection handler — route by URL path ────────────────────────────────
756→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
757→  const path = req.url ?? "/";
758→  console.log(`[ws connected] path=${path}`);
759→
760→  if (path === "/browser") {
761→    // Send full state BEFORE adding to browserSockets so that live
762→    // relay broadcasts don't interleave with the history replay.
763→    sendFullStateToSocket(ws);
764→    browserSockets.add(ws);
765→
766→    ws.on("message", (data) => {
767→      handleBrowserMessage(data.toString(), ws);
768→    });
769→
770→    ws.on("close", () => {
771→      console.log("[browser disconnected]");
772→      browserSockets.delete(ws);
773→      // Do NOT kill agents — keep them alive for reconnect
774→    });
775→  } else if (path.startsWith("/claude/")) {
776→    // Parse agentId from /claude/<agentId>
777→    const agentId = path.slice("/claude/".length);
778→    const agent = agents.get(agentId);
779→
780→    if (!agent) {
781→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
782→      ws.close();
783→      return;
784→    }
785→
786→    agent.claudeSocket = ws;
787→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
788→
789→    // Notify browsers that CLI is connected
790→    sendToBrowser({ type: "cli_connected", agentId });
791→
792→    // Flush any pending messages queued while CLI was disconnected
793→    if (agent.pendingMessages.length > 0) {
794→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
795→      for (const queued of agent.pendingMessages) {
796→        ws.send(queued + "\n");
797→      }
798→      agent.pendingMessages = [];
799→      persistAgentSync(agent);
800→    }
801→
802→    // Send the pending prompt immediately — CLI 2.1.42+ waits for the
803→    // server to send the first user message rather than emitting
804→    // hook_started/hook_response on connect.
805→    if (agent.pendingPrompt && ws.readyState === WebSocket.OPEN) {
806→      const userMsg = JSON.stringify({
807→        type: "user",
808→        message: { role: "user", content: agent.pendingPrompt },
809→        parent_tool_use_id: null,
810→        session_id: agent.sessionId ?? "",
811→      });
812→      console.log(`[server → claude:${agentId}] sending pending prompt`);
813→      ws.send(userMsg + "\n");
814→      agent.pendingPrompt = null;
815→      setAgentStatus(agentId, "thinking");
816→    }
817→
818→    ws.on("message", (data) => {
819→      handleClaudeMessage(agentId, data.toString());
820→    });
821→
822→    ws.on("close", () => {
823→      console.log(`[claude:${agentId} CLI disconnected]`);
824→      if (agent.claudeSocket === ws) {
825→        agent.claudeSocket = null;
826→        if (agent.status !== "error") {
827→          setAgentStatus(agentId, "done");
828→          sendToBrowser({ type: "cli_disconnected", agentId });
829→
830→          // Auto-complete any task linked to this agent
831→          for (const task of tasks.values()) {
832→            if (task.agentId === agentId && task.status !== "done") {
833→              task.status = "done";
834→              task.updatedAt = Date.now();
835→              persistTasks();
836→              broadcastTaskList();
837→              break;
838→            }
839→          }
840→        }
841→      }
842→    });
843→  } else {
844→    console.log(`[ws] unknown path: ${path}, closing`);
845→    ws.close();
846→  }
847→});
848→
849→// ── Graceful shutdown ─────────────────────────────────────────────────────
850→
851→function shutdown() {
852→  console.log("[ws server] shutting down...");
853→
854→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
855→  // so CLI processes can reconnect if the server restarts.
856→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
857→  store.flushAll(allPersisted);
858→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
859→
860→  taskStore.flush(Array.from(tasks.values()));
861→  console.log(`[ws server] saved ${tasks.size} tasks to disk`);
862→
863→  wss.close();
864→  process.exit(0);
865→}
866→
867→process.on("SIGTERM", shutdown);
