122→          <div className="flex gap-1">
123→            <Button size="xs" onClick={handleSaveEdit}>
124→              <Check className="size-3 mr-1" />
125→              Save
126→            </Button>
127→            <Button size="xs" variant="ghost" onClick={handleCancelEdit}>
128→              Cancel
129→            </Button>
130→          </div>
131→        </div>
132→      ) : (
133→        task.description && (
134→          <p className="mt-1 text-muted-foreground line-clamp-2">{task.description}</p>
135→        )
136→      )}
137→
138→      <div className="mt-2 flex items-center justify-between">
139→        <button
140→          className={cn(
141→            "rounded-full border px-2 py-0.5 text-[10px] font-medium transition-colors hover:brightness-125",
142→            STATUS_COLORS[task.status]
143→          )}
144→          onClick={() => onUpdate(task.id, { status: NEXT_STATUS[task.status] })}
145→          title={`Click to change to "${STATUS_LABELS[NEXT_STATUS[task.status]]}"`}
146→        >
147→          {STATUS_LABELS[task.status]}
148→        </button>
149→
150→        {task.agentId && (
151→          <button
152→            className="flex items-center gap-1 text-[10px] text-primary hover:underline"
153→            onClick={() => onSelectAgent(task.agentId!)}
154→          >
155→            <ExternalLink className="size-2.5" />
156→            view agent
157→          </button>
158→        )}
159→      </div>
160→    </div>
