  1→"use client";
  2→
  3→import { useState } from "react";
  4→import { Play, Trash2, ExternalLink, Check } from "lucide-react";
  5→import { Button } from "@/components/ui/button";
  6→import { cn } from "@/lib/utils";
  7→import type { Task, TaskStatus, TaskPriority } from "@/lib/types";
  8→
  9→const PRIORITY_COLORS: Record<TaskPriority, string> = {
 10→  urgent: "bg-red-500/20 text-red-400 border-red-500/30",
 11→  high: "bg-orange-500/20 text-orange-400 border-orange-500/30",
 12→  medium: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
 13→  low: "bg-muted text-muted-foreground border-border",
 14→};
 15→
 16→const STATUS_COLORS: Record<TaskStatus, string> = {
 17→  todo: "border-border text-muted-foreground",
 18→  "in-progress": "bg-blue-500/20 text-blue-400 border-blue-500/30",
 19→  done: "bg-green-500/20 text-green-400 border-green-500/30",
 20→};
 21→
 22→const STATUS_LABELS: Record<TaskStatus, string> = {
 23→  todo: "todo",
 24→  "in-progress": "in progress",
 25→  done: "done",
 26→};
 27→
 28→const NEXT_STATUS: Record<TaskStatus, TaskStatus> = {
 29→  todo: "in-progress",
 30→  "in-progress": "done",
 31→  done: "todo",
 32→};
 33→
 34→interface TaskCardProps {
 35→  task: Task;
 36→  onUpdate: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
 37→  onDelete: (taskId: string) => void;
 38→  onDelegate: (taskId: string) => void;
 39→  onSelectAgent: (agentId: string) => void;
 40→}
 41→
 42→export function TaskCard({ task, onUpdate, onDelete, onDelegate, onSelectAgent }: TaskCardProps) {
 43→  const [editing, setEditing] = useState(false);
 44→  const [editTitle, setEditTitle] = useState(task.title);
 45→  const [editDesc, setEditDesc] = useState(task.description);
 46→
 47→  const handleSaveEdit = () => {
 48→    if (!editTitle.trim()) return;
 49→    onUpdate(task.id, { title: editTitle.trim(), description: editDesc.trim() });
 50→    setEditing(false);
 51→  };
 52→
 53→  const handleCancelEdit = () => {
 54→    setEditTitle(task.title);
 55→    setEditDesc(task.description);
 56→    setEditing(false);
 57→  };
 58→
 59→  return (
 60→    <div className="group rounded-md border bg-card p-3 text-xs">
 61→      <div className="flex items-start justify-between gap-2">
 62→        <div className="flex items-center gap-1.5 min-w-0">
 63→          <span
 64→            className={cn("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-medium border", PRIORITY_COLORS[task.priority])}
 65→          >
 66→            {task.priority}
 67→          </span>
 68→          {editing ? (
 69→            <input
 70→              className="min-w-0 flex-1 bg-transparent font-medium outline-none border-b border-primary"
 71→              value={editTitle}
 72→              onChange={(e) => setEditTitle(e.target.value)}
 73→              onKeyDown={(e) => {
 74→                if (e.key === "Enter") handleSaveEdit();
 75→                if (e.key === "Escape") handleCancelEdit();
 76→              }}
 77→              autoFocus
 78→            />
 79→          ) : (
 80→            <span
 81→              className={cn(
 82→                "truncate font-medium cursor-pointer",
 83→                task.status === "done" && "line-through text-muted-foreground"
 84→              )}
 85→              onDoubleClick={() => setEditing(true)}
 86→            >
 87→              {task.title}
 88→            </span>
 89→          )}
 90→        </div>
 91→        <div className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
 92→          {!task.agentId && task.status !== "done" && (
 93→            <Button
 94→              variant="ghost"
 95→              size="icon-xs"
 96→              onClick={() => onDelegate(task.id)}
