import WebSocket from 'ws';

const ws = new WebSocket('ws://localhost:9900/browser');

const tasks = [
  { title: "Message timestamps", description: "There are no timestamps on messages currently. Adding relative times (\"2m ago\") or hover-to-see-absolute-time would help track conversation flow.", priority: "high" },
  { title: "Markdown rendering", description: "Assistant messages are rendered as plain text. Claude outputs markdown (code blocks, headers, lists, bold) — rendering it properly would massively improve readability.", priority: "high" },
  { title: "Search/filter messages", description: "Long conversations are impossible to navigate. A Cmd+F style search bar to filter messages by content or tool name would help.", priority: "high" },
  { title: "Syntax highlighting in tool calls", description: "Control request cards show raw JSON in a plain <code> block. Syntax highlighting (or at minimum, pretty-printing with indentation) would make tool approval much easier.", priority: "high" },
  { title: "Streaming text display", description: "Currently messages appear all at once after processing. Showing text as it streams in would make the UI feel much more responsive.", priority: "high" },
  { title: "Multi-pane / split view", description: "You can only see one agent at a time. Side-by-side or tabbed views would let you monitor multiple agents working in parallel.", priority: "medium" },
  { title: "Copy message button", description: "No way to copy a message's content. A small copy icon on hover would be useful.", priority: "medium" },
  { title: "Keyboard shortcuts", description: "No keyboard shortcuts for common actions (send on Enter, switch agents with Ctrl+1/2/3, approve/deny tool calls).", priority: "medium" },
  { title: "Auto-scroll toggle", description: "The auto-scroll behavior could be annoying when reading history. A \"pin to bottom\" toggle that disables when you scroll up and shows a \"jump to bottom\" button.", priority: "medium" },
  { title: "Message export", description: "Export a conversation as markdown or JSON for sharing or documentation.", priority: "medium" },
  { title: "Tool call result previews", description: "Condensed tool groups tell you what was called but not the results. Showing truncated output inline would add context.", priority: "low" },
  { title: "Agent cost/duration summary", description: "The result message has cost data. A small summary card at the top showing total cost, duration, and turn count per agent.", priority: "low" },
  { title: "Connection status toast", description: "WebSocket reconnection happens silently. A brief toast notification when connection drops/restores would build trust.", priority: "low" },
  { title: "Empty state", description: "When no agent is selected, the chat area is blank. A nice empty state with quick-start instructions would help.", priority: "low" },
  { title: "Resizable sidebar", description: "The sidebar width is fixed. A drag handle to resize would let users optimize their layout.", priority: "low" },
];

ws.on('open', () => {
  let i = 0;
  function sendNext() {
    if (i >= tasks.length) {
      setTimeout(() => {
        ws.close();
        process.exit(0);
      }, 500);
      return;
    }
    const t = tasks[i];
    ws.send(JSON.stringify({
      type: "create_task",
      title: t.title,
      description: t.description,
      priority: t.priority,
    }));
    i++;
    setTimeout(sendNext, 100);
  }
  sendNext();
});

ws.on('error', (err) => {
  console.error('WS error:', err.message);
  process.exit(1);
});
